export type ProductJourneyCheckpointId = typeof currentProductJourneyCheckpointPresentation[number]["checkpointId"]

export const currentProductJourneyCheckpointIds = currentProductJourneyCheckpointPresentation
  .slice().sort((left, right) => left.order - right.order)
  .map((entry) => entry.checkpointId) as readonly ProductJourneyCheckpointId[]

export const currentProductJourneyCheckpointLabels = Object.fromEntries(
  currentProductJourneyCheckpointPresentation.map((entry) => [entry.checkpointId, entry.label]),
) as Readonly<Record<ProductJourneyCheckpointId, string>>

export const currentProductJourneyRecordGroupByCheckpoint = Object.fromEntries(
  currentProductJourneyCheckpointPresentation
    .filter((entry) => entry.recordGroup !== undefined)
    .map((entry) => [entry.checkpointId, entry.recordGroup!]),
) as Readonly<Partial<Record<ProductJourneyCheckpointId, string>>>

export function currentProductJourneyCheckpointForRecordGroup(group: string): ProductJourneyCheckpointContract | undefined {
  return currentProductJourneyCheckpointPresentation.find((entry) => entry.recordGroup === group)
}

export function currentProductJourneyCompatibilityCheckpointId(checkpointId: ProductJourneyCheckpointId): ProductJourneyCheckpointId | "design-implementation-handoff" {
  const checkpoint = currentProductJourneyCheckpoint(checkpointId)
  return (checkpoint.adoptionFollowThrough.compatibilityCheckpointId ?? checkpoint.checkpointId) as ProductJourneyCheckpointId | "design-implementation-handoff"
}

export function currentProductJourneyCheckpoint(id: ProductJourneyCheckpointId): ProductJourneyCheckpointContract {
  const value = currentProductJourneyCheckpointPresentation.find((entry) => entry.checkpointId === id)
  if (!value) throw new Error(`Unknown Product Journey checkpoint ${id}`)
  return value
}
